assert [a['id'] for a in out['answers']]==['Q01','Q02','Q03','Q04','Q05']
for a in out['answers']:
    for sp in a['source_passages']:
        assert sp['quotation'] and sp['quotation'] in guide
print('group Q01-Q05 saved; quotation and labeled-application checks passed')
